private void xrLabel16_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
       if (GetCurrentColumnValue("IDMENYREPAGESE")!= null)
{
  switch (this.GetCurrentColumnValue("IDMENYREPAGESE").ToString())
            {
                case "0":
                    xrLabel16.Text = "Me mirebesim";
                    break;
                case "4":
                    xrLabel16.Text = "Pagese";
                    break;
                case "5":
                    xrLabel16.Text = "Pagese Automatike";
                    break;
               case "6":
                    xrLabel16.Text = "Cash & Bank";
                    break;
 		          case "7":
                    xrLabel16.Text = "Me parapagim";
                    break;
		          case "8":
                    xrLabel16.Text = "Arke";
                    break;
		           case "9":
                    xrLabel16.Text = "Karte krediti";
                    break;
		          case "10":
                    xrLabel16.Text = "Pezull";
                    break;
		          case "11":
                    xrLabel16.Text = "Banke";
                    break;
                default:
                    break;
    }
 }
}

