private void xrTableCell37_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
	if (GetCurrentColumnValue("monedha_kf").ToString() == GetCurrentColumnValue("MONEDHANDERMARJE").ToString()){
		e.Result = (totalipatvsh - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) - Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL")))/Convert.ToDouble(GetCurrentColumnValue("KURSIIDTDOKFATURE"));
	} else {
		e.Result = totalipatvsh - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) - Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL"));

	}
      e.Handled = true;
}

